'use strict';
let chosenCrop='lettuce', plantingMethod='seed', cropCategory='all', cropQuery='', taskMode='list', taskDate=day();
let plantingDraft={checks:[],photos:[],memo:''};
let diagnosisDraft={kind:'',symptoms:[],photos:[]};
let diagnosisReturn='detail';
let farmFormLocation=null;
let tasksBack='farms';  // '오늘 할 일 모아보기'를 연 곳(농장 목록 또는 농장 화면). 뒤로가기는 그곳으로 돌아간다
const baseNavigate=navigate;
navigate=function(next){
  if(next==='tasks')tasksBack=view==='garden'?'garden':'farms';
  if(next==='add'||next==='edit')farmFormLocation=null;
  if(next==='select'&&view==='garden')plantingMethod='seed';
  if(next==='diagnosis')diagnosisReturn=view==='leaf-result'?'leaf-result':view==='detail'?'detail':'menu';
  baseNavigate(next);
};
const baseFormPage=formPage;
formPage=function(edit){
  return baseFormPage(edit).replace(/(<input id="farm-region"[^>]*>)/,
    '<div class="region-row">$1<button type="button" class="secondary location-button" data-feature="farm-location">⌖ 현재 위치</button></div><ul id="region-suggest" class="region-suggest" role="listbox" aria-label="비슷한 지역" hidden></ul><small class="region-credit">현재 위치 지역명: <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">© OpenStreetMap contributors</a></small>');
};
// 지역 입력 자동완성: 입력이 멈추면(0.35초) 서버(카카오 주소 검색)에서 비슷한 지역을 받아 목록으로 보여 준다
let regionResults=[],regionTimer=0,regionSeq=0;
const regionList=()=>document.querySelector('#region-suggest');
function showRegionResults(items){
  const list=regionList();
  if(!list)return;
  regionResults=items;
  list.innerHTML=items.map((p,i)=>`<li role="option"><button type="button" class="region-option" data-feature="region-pick" data-index="${i}">${esc(p.label)}</button></li>`).join('');
  list.hidden=!items.length;
}
app.addEventListener('input',event=>{
  if(event.target.id!=='farm-region')return;
  farmFormLocation=null;
  clearTimeout(regionTimer);
  const text=event.target.value.trim(),seq=++regionSeq;
  if(text.length<2){showRegionResults([]);return}
  regionTimer=setTimeout(async()=>{
    try{
      const r=await hostApi('places',{q:text});
      if(seq===regionSeq)showRegionResults(r.places);
    }catch{if(seq===regionSeq)showRegionResults([])}  // 검색이 안 돼도 직접 입력해서 저장할 수 있다
  },350);
});
app.addEventListener('click',async event=>{
  const button=event.target.closest('[data-feature="region-pick"]');
  if(!button)return;
  const input=document.querySelector('#farm-region'),place=regionResults[Number(button.dataset.index)];
  if(!input||!place)return;
  regionSeq++;
  input.value=place.label;
  showRegionResults([]);
  farmFormLocation=null;
  let found=Number.isFinite(place.latitude)&&Number.isFinite(place.longitude)?place:null;
  if(!found){  // 장소 검색에서 뽑은 후보는 좌표가 없어서, 이름으로 한 번 더 찾아 좌표를 받는다
    try{found=(await hostApi('places',{q:place.label})).places.find(p=>p.label===place.label&&Number.isFinite(p.latitude))||null}catch{}
  }
  if(!input.isConnected||input.value!==place.label)return;
  if(found){farmFormLocation={latitude:found.latitude,longitude:found.longitude,label:place.label}}
  else toast('이 지역의 위치를 찾지 못했어요. 지역명만 저장되고, 날씨는 다른 지역을 고르거나 현재 위치 버튼으로 지정해 주세요.');
});
app.addEventListener('click',event=>{
  const button=event.target.closest('[data-feature="farm-location"]');
  if(!button)return;
  if(!navigator.geolocation){toast('이 브라우저에서는 현재 위치를 사용할 수 없어요. 지역을 직접 입력해 주세요.');return;}
  const input=document.querySelector('#farm-region');
  button.disabled=true;
  button.textContent='위치 확인 중…';
  const previousValue=input.value;
  navigator.geolocation.getCurrentPosition(async position=>{
    if(!input.isConnected)return;
    button.textContent='지역명 확인 중…';
    try{
      const latitude=Number(position.coords.latitude.toFixed(4)),longitude=Number(position.coords.longitude.toFixed(4));
      const label=await GardenWeather.reverseGeocode(latitude,longitude);
      if(!input.isConnected||input.value!==previousValue)return;
      farmFormLocation={latitude,longitude,label};
      input.value=label;
      button.textContent='⌖ 위치 설정됨';
      toast(`${label} 지역으로 설정했어요.`);
    }catch{
      if(button.isConnected){button.textContent='⌖ 현재 위치';toast('지역명을 확인하지 못했어요. 다시 시도하거나 지역을 직접 입력해 주세요.')}
    }finally{if(button.isConnected){button.disabled=false;button.textContent=farmFormLocation&&input.value===farmFormLocation.label?'⌖ 위치 설정됨':'⌖ 현재 위치'}}
  },error=>{
    if(!button.isConnected)return;
    button.disabled=false;
    button.textContent='⌖ 현재 위치';
    toast(error.code===1?'브라우저 위치 권한을 허용하거나 지역을 직접 입력해 주세요.':'현재 위치를 확인하지 못했어요. 다시 시도하거나 지역을 입력해 주세요.');
  },{enableHighAccuracy:false,timeout:10000,maximumAge:60000});
});
let growthDate=day();
function refreshGrowth(){
  if(day()!==growthDate){growthDate=day();render();}
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshGrowth();});
setInterval(refreshGrowth,60000);
const categories={lettuce:'vegetable',cucumber:'fruit',pepper:'fruit',eggplant:'fruit',zucchini:'fruit',tomato:'fruit',potato:'vegetable'};
const careItems=(p,date=day())=>p.harvestedAt&&date>p.harvestedAt?[]:[['water','물주기 확인','흙이 말랐는지 손가락으로 확인해요'],['care',p.kind==='tomato'?'곁순 따기':'겉잎 상태 보기',p.kind==='tomato'?'아래쪽 곁순을 손으로 떼어주세요':'시든 잎이 있으면 떼어주세요'],['observe','잎 관찰하기','잎의 색과 반점을 살펴보고 상태를 기록해요']];
const completed=(p,key,date=day())=>p.taskChecks?.[date]?.includes(key)||key==='water'&&p.wateredAt===date;
const leafStatuses=[['healthy','건강해요'],['yellow','잎이 노래요'],['spots','반점이 있어요'],['wilted','시들었어요'],['other','기타 변화가 있어요']];
const harvestReady=p=>GardenGrowth.elapsed(p.plantedAt,day())>=meta(p).days;
function leafStatusSection(p){return `<section class="leaf-observation" aria-label="잎 상태 관찰"><div class="field-label">직접 확인한 잎 상태 <span class="count">선택</span></div><p class="help">잎을 살펴보고 해당하는 상태를 골라주세요. 사진만 기록해도 돼요.</p><div class="leaf-status-options">${leafStatuses.map(([key,label])=>`<button type="button" class="leaf-status-option ${p.draftLeafStatus===key?'active':''}" data-feature="leaf-status" data-value="${key}" aria-pressed="${p.draftLeafStatus===key}">${label}</button>`).join('')}</div>${p.draftLeafStatus==='other'?`<div class="field leaf-other-field"><label class="field-label" for="leaf-other">어떤 변화가 있었나요?</label><textarea id="leaf-other" maxlength="200" placeholder="예: 잎 끝이 갈색으로 변했어요.">${esc(p.draftLeafOther||'')}</textarea></div>`:''}</section>`}
function photoSection(photos=[]){return `<div class="field"><div class="field-label">사진 <span class="count">사진과 함께 기록해요</span></div><div class="photo-strip">${photos.map((src,i)=>`<button class="photo-thumb" data-feature="remove-photo" data-index="${i}" aria-label="사진 ${i+1} 삭제"><img src="${esc(src)}" alt="작물 사진"><span>×</span></button>`).join('')}<label class="photo-add">📷<br>사진 추가<input id="feature-photo" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden></label></div></div>`}
function selectionPage(){const f=current();if(!f)return farmsPage();return `<main class="page">${head('작물 선택','garden')}<p class="help">${esc(f.name)} · ${pendingPlot+1}번째 칸에 심어요</p><div class="feature-tabs">${[['seed','씨앗','1단계부터 키워요'],['seedling','모종','3단계부터 시작해요']].map(([key,label,sub])=>`<button data-feature="method" data-value="${key}" class="${plantingMethod===key?'active':''}"><b>${label}</b><small>${sub}</small></button>`).join('')}</div><input id="crop-search" placeholder="작물 이름을 검색하세요" value="${esc(cropQuery)}"><div class="category-tabs">${[['all','전체'],['vegetable','채소'],['fruit','과일채소']].map(([key,label])=>`<button data-feature="category" data-value="${key}" class="${cropCategory===key?'active':''}">${label}</button>`).join('')}</div><p class="help">수확 기간은 환경과 품종에 따라 달라요</p><div class="selection-grid" id="selection-grid">${cropCards()}</div></main>${footer(`<button class="primary" data-feature="prepare">선택한 작물로 계속 (${CROPS.find(c=>c.id===chosenCrop).name} · ${plantingMethod==='seed'?'씨앗':'모종'})</button>`)}`}
function cropCards(){const matches=CROPS.filter(c=>(cropCategory==='all'||categories[c.id]===cropCategory)&&c.name.includes(cropQuery));return matches.length?matches.map(c=>`<button class="selection-card ${chosenCrop===c.id?'active':''}" data-feature="choose" data-value="${c.id}"><span class="selection-art">${CropArt.svg(c.id,5,true)}</span><b>${c.name}</b><small>수확 약 ${c.days}일 · ${categories[c.id]==='fruit'?'과일채소':'채소'}</small>${chosenCrop===c.id?'<span class="selected-mark">✓</span>':''}</button>`).join(''):'<p class="help">검색 결과가 없어요.</p>'}
// 되돌릴 수 없는 동작 전에 한 번 더 묻는 앱 안의 확인 창(바깥을 누르거나 Esc를 누르면 취소). 누르면 true, 취소하면 false를 돌려준다
function askConfirm({title,message,confirmLabel='확인'}){
  return new Promise(resolve=>{
    const root=document.createElement('div');
    root.className='confirm-backdrop';
    root.innerHTML=`<div class="confirm" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><p id="confirm-title" class="confirm-title">${esc(title)}</p>${message?`<p class="confirm-message">${esc(message)}</p>`:''}<div class="confirm-actions"><button type="button" class="confirm-cancel">취소</button><button type="button" class="confirm-ok">${esc(confirmLabel)}</button></div></div>`;
    const position=()=>{
      const rect=document.querySelector('.phone-shell')?.getBoundingClientRect();
      if(!rect)return;
      const viewport=window.visualViewport;
      const viewTop=viewport?.offsetTop||0,viewLeft=viewport?.offsetLeft||0;
      // 세로로 긴 미리보기 영역에서는 실제 휴대폰 화면 높이만큼만 중앙 기준으로 삼는다.
      const visibleHeight=Math.min(viewport?.height||window.innerHeight,rect.width*2.15);
      const viewBottom=viewTop+visibleHeight;
      const viewRight=viewLeft+(viewport?.width||window.innerWidth);
      const top=Math.max(viewTop,rect.top),bottom=Math.min(viewBottom,rect.bottom);
      const left=Math.max(viewLeft,rect.left),right=Math.min(viewRight,rect.right);
      root.style.inset=`${top}px ${Math.max(0,window.innerWidth-right)}px ${Math.max(0,window.innerHeight-bottom)}px ${left}px`;
    };
    const onKey=e=>{if(e.key==='Escape')done(false)};
    const done=v=>{
      document.removeEventListener('keydown',onKey);
      window.removeEventListener('resize',position);
      window.removeEventListener('scroll',position);
      window.visualViewport?.removeEventListener('resize',position);
      window.visualViewport?.removeEventListener('scroll',position);
      root.remove();
      resolve(v);
    };
    root.addEventListener('click',e=>{if(e.target===root)done(false)});
    root.querySelector('.confirm-cancel').addEventListener('click',()=>done(false));
    root.querySelector('.confirm-ok').addEventListener('click',()=>done(true));
    document.addEventListener('keydown',onKey);
    window.addEventListener('resize',position);
    window.addEventListener('scroll',position,{passive:true});
    window.visualViewport?.addEventListener('resize',position);
    window.visualViewport?.addEventListener('scroll',position);
    document.body.append(root);
    position();
    root.querySelector('.confirm-cancel').focus();
  });
}
function preparationPage(){const ready=[0,1,2].every(i=>plantingDraft.checks.includes(i));return `<main class="page">${head('심기 전 준비','select')}<div class="seed-sign"><b>${CROPS.find(c=>c.id===chosenCrop).name}</b><small>${plantingMethod==='seed'?'씨앗':'모종'}으로 시작 · ${pendingPlot+1}번째 칸</small></div><h3>미리 해 두면 좋아요</h3>${[['흙 고르기','삽으로 흙을 부드럽게 갈아주세요'],['간격 맞추기','품종에 맞는 간격을 확인해 주세요'],['준비물 챙기기',plantingMethod==='seed'?'씨앗 · 물뿌리개 · 모종삽':'모종 · 물뿌리개 · 모종삽']].map(([label,sub],i)=>`<button class="check-card" data-feature="precheck" data-index="${i}"><span class="check-box ${plantingDraft.checks.includes(i)?'checked':''}">${plantingDraft.checks.includes(i)?'✓':''}</span><span><b>${label}</b><small>${sub}</small></span></button>`).join('')}${photoSection(plantingDraft.photos)}<div class="field"><label class="field-label" for="feature-memo">메모</label><textarea id="feature-memo" maxlength="500" placeholder="준비하면서 한 일을 적어보세요 (선택)">${esc(plantingDraft.memo)}</textarea></div><div class="info">ⓘ ${ready?'준비가 끝났어요. 아래 버튼을 누르면 오늘부터 재배가 시작돼요.':'준비 항목 3개를 모두 체크하면 작물을 심을 수 있어요.'}</div></main>${footer(`<button class="primary" data-feature="plant" ${ready?'':'disabled'}>심었어요</button>`)}`}
detailPage=function(){
  const f=current(),p=f?.plots[plotIndex];
  if(!p)return gardenPage();
  const items=careItems(p),pending=items.filter(([key])=>!completed(p,key)),days=GardenGrowth.elapsed(p.plantedAt,day()),remaining=Math.max(0,meta(p).days-days);
  const ready=harvestReady(p);
  return `<main class="page">${head(meta(p).name,'garden')}
    <div class="detail-subhead"><small>${esc(f.name)} · 심은 지 ${days+1}일</small><span class="pill">${p.harvestedAt?'수확 완료':GardenGrowth.labels[p.stage-1]+' · '+p.stage+'/5단계'}</span><button class="icon-btn" data-feature="delete-crop" aria-label="작물 삭제"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 10v7m4-7v7"/></svg></button></div>
    ${p.lastLeafObservation?`<div class="leaf-status-summary"><b>최근 잎 관찰 · ${esc(p.lastLeafObservation.date)}</b><span>${esc(p.lastLeafObservation.label||'사진 기록')}</span></div>`:''}
    ${p.harvestedAt?`<div class="harvest-banner"><b>수확을 마쳤어요</b><p>${esc(p.harvestedAt)}에 수확했어요. 재배일지는 계속 남길 수 있어요.</p></div>`:ready?`<div class="harvest-banner"><b>수확할 때가 됐어요</b><p>재배기간 ${meta(p).days}일을 채웠어요. 작물 상태를 살핀 뒤 수확해 주세요.</p><button class="primary" data-feature="harvest">수확하기</button></div>`:`<p class="help">수확까지 약 ${remaining}일 남았어요. 재배기간은 환경과 품종에 따라 달라질 수 있어요.</p>`}
    ${items.length?`<div class="field-label">오늘 할 일 <span class="count">완료 ${pending.length?`${items.length-pending.length} / ${items.length}`:'0 / 0'}</span></div>${pending.length?pending.map(([key,label,sub])=>`<div class="check-card"><button class="check-hit" data-feature="${key==='observe'?'observe':'check'}" data-value="${key}" aria-label="${label}" aria-pressed="false"><span class="check-box"></span></button><button class="task-content" data-feature="${key==='observe'?'observe':'check'}" data-value="${key}"><b>${label}${key==='observe'?'<span class="pill">주 1회 · 상태 기록</span>':''}</b><small>${sub}</small></button></div>`).join(''):'<div class="tk-empty-task"><span class="tk-empty-icon" aria-hidden="true">🌱</span><div><strong>오늘 할 일 끝!</strong><p>지금 할 일은 모두 마쳤어요.</p></div></div>'}`:''}
    ${photoSection(p.draftPhotos)}
    <div class="field"><label class="field-label" for="feature-memo">메모</label><textarea id="feature-memo" maxlength="500" placeholder="오늘 텃밭 상태를 적어보세요 (선택)">${esc(p.draftMemo||'')}</textarea></div>
  </main>${footer('<button class="secondary diagnosis-button" data-feature="diagnosis">AI진단</button><button class="primary" data-feature="journal">일지 올리기</button>')}`};
function leafPage(){const p=current()?.plots[plotIndex];if(!p)return gardenPage();const editing=!!journalEdit&&!!journalEntries().find(r=>r.id===journalEdit)?.leaf;return `<main class="page leaf-page">${head(editing?'잎 관찰 수정':'잎 관찰하기',editing&&journalFlowOrigin==='journal'?'journal':'detail')}<p class="help">잎 사진을 찍거나 올린 뒤 상태를 기록해 주세요.</p>${photoSection(p.leafDraftPhotos||[])}${leafStatusSection(p)}<div class="info">ⓘ 사진을 올려도 자동 판정은 아직 진행되지 않아요. 기록한 내용은 재배일지에 남습니다.</div></main>${footer(`<button class="primary" data-feature="leaf-save">${editing?'수정 완료':'관찰 기록하기'}</button>`)}`}
function leafResultPage(){const p=current()?.plots[plotIndex],observation=p?.lastLeafObservation;if(!observation)return leafPage();return `<main class="page leaf-result-page">${head('잎 관찰 결과',journalFlowOrigin==='journal'?'journal':'garden')}<span class="pill">관찰 완료</span><div class="leaf-result-image">${observation.photo?`<img src="${esc(observation.photo)}" alt="기록한 잎 사진">`:'<span aria-hidden="true">🌿</span>'}</div><div class="leaf-result-card"><b>${observation.label?esc(observation.label):'잎 사진을 기록했어요'}</b><p>${esc(observation.date)}에 직접 관찰한 내용이에요. AI 판정 결과는 아직 연결되지 않았어요.</p></div><p class="help">상태가 달라지면 다시 관찰해 기록할 수 있어요.</p></main>${footer(`<button class="primary" data-feature="diagnosis">AI 진단 화면 보기</button><button class="secondary" data-feature="observe">다시 관찰하기</button><button class="secondary" data-feature="leaf-back">${journalFlowOrigin==='journal'?'재배일지로 돌아가기':'텃밭으로 돌아가기'}</button>`)}`}
function diagnosisPage(){const symptoms=[['yellow','잎이 변색'],['wilted','시듦'],['spots','잎의 반점'],['holes','구멍'],['slow','성장 느림'],['fruit','과실 이상'],['other','기타']],editing=!!journalEdit&&!!journalEntries().find(r=>r.id===journalEdit)?.diagnosis;return `<main class="page diagnosis-page">${head('AI 진단',editing?(journalFlowOrigin==='journal'?'journal':diagnosisReturn):diagnosisReturn)}<p class="help">작물과 잎 상태를 기록해 두세요. 사진 판정 기능은 진단 데이터가 연결되면 사용할 수 있어요.</p><div class="field-label">1. 어떤 작물인가요?</div><div class="diagnosis-crops">${CROPS.map(c=>`<button type="button" class="diagnosis-crop ${diagnosisDraft.kind===c.id?'active':''}" data-feature="diagnosis-crop" data-value="${c.id}" aria-pressed="${diagnosisDraft.kind===c.id}">${c.name}</button>`).join('')}</div><div class="field-label">2. 어떤 증상이 있나요?</div><div class="leaf-status-options">${symptoms.map(([key,label])=>`<button type="button" class="leaf-status-option ${diagnosisDraft.symptoms.includes(key)?'active':''}" data-feature="diagnosis-symptom" data-value="${key}" aria-pressed="${diagnosisDraft.symptoms.includes(key)}">${label}</button>`).join('')}</div><div class="field-label diagnosis-photo-label">3. 사진을 찍어주세요</div>${photoSection(diagnosisDraft.photos)}${editing?`<div class="field"><label class="field-label" for="diagnosis-result">기존 진단 결과</label><textarea id="diagnosis-result" maxlength="500">${esc(diagnosisDraft.result||'')}</textarea></div>`:'<div class="info">ⓘ 현재는 작물·증상·사진만 준비할 수 있어요. AI 진단 결과는 아직 제공되지 않습니다.</div>'}</main>${footer(editing?'<button class="primary" data-feature="diagnosis-save">수정 완료</button>':'<button class="primary" type="button" disabled aria-disabled="true">진단 데이터 연결 후 이용 가능</button>')}`}
const baseExtraPage=extraPage;
extraPage=function(){if(view==='leaf')return leafPage();if(view==='leaf-result')return leafResultPage();if(view==='diagnosis')return diagnosisPage();return baseExtraPage()};
tasksPage=function(){const date=taskMode==='calendar'?taskDate:day();return `<main class="page">${head('오늘 할 일',tasksBack==='garden'&&current()?'garden':'farms')}<div class="feature-tabs">${[['list','목록'],['calendar','캘린더']].map(([key,label])=>`<button data-feature="task-mode" data-value="${key}" class="${taskMode===key?'active':''}">${label}</button>`).join('')}</div>${taskMode==='calendar'?`<label class="field-label" for="task-date">날짜 선택</label><input id="task-date" type="date" value="${date}" max="${day()}">`:''}${state.farms.map(f=>{const tasks=f.plots.flatMap((p,i)=>p&&p.plantedAt<=date&&(!p.harvestedAt||date<=p.harvestedAt)?careItems(p,date).filter(([key])=>!completed(p,key,date)).map(([key,label,sub])=>({p,i,key,label,sub})):[]);return `<h3>${esc(f.name)} <span class="task-count">${tasks.length}</span></h3>${tasks.length?tasks.map(t=>`<button class="check-card" data-feature="open-task" data-id="${esc(f.id)}" data-index="${t.i}"><span class="check-box"></span><span><b>${t.label}</b><small>${meta(t.p).name} · ${t.sub}</small></span><span class="chevron">›</span></button>`).join(''):'<div class="no-tasks">이 날짜에 남은 할 일이 없어요</div>'}`}).join('')}<p class="help">할 일을 누르면 작물 관리 화면으로 이동해요.</p></main>`};
app.addEventListener('input',e=>{if(e.target.id==='crop-search'){cropQuery=e.target.value;document.querySelector('#selection-grid').innerHTML=cropCards()}if(e.target.id==='feature-memo'){if(view==='prepare')plantingDraft.memo=e.target.value;else if(view==='detail')current().plots[plotIndex].draftMemo=e.target.value}if(e.target.id==='leaf-other'&&view==='leaf')current().plots[plotIndex].draftLeafOther=e.target.value});
app.addEventListener('change',async e=>{if(e.target.id==='task-date'){taskDate=e.target.value;render()}if(e.target.id!=='feature-photo')return;const farm=current(),p=view==='diagnosis'?diagnosisDraft:(view==='detail'||view==='leaf')?farm.plots[plotIndex]:plantingDraft;const preparing=view==='prepare';const photos=preparing||view==='diagnosis'?p.photos:view==='leaf'?(p.leafDraftPhotos||=[]):(p.draftPhotos||=[]);try{for(const file of Array.from(e.target.files).slice(0,4-photos.length)){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('JPG, PNG, WEBP 사진을 선택해 주세요.');continue}if(file.size>10*1024*1024){toast('사진은 10MB 이하로 선택해 주세요.');continue}const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');const scale=Math.min(1,1000/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();photos.push(canvas.toDataURL('image/jpeg',.7))}if(view==='detail'||view==='leaf')save();if(current()===farm&&(preparing?view==='prepare':view==='diagnosis'||(view==='detail'||view==='leaf')&&farm.plots[plotIndex]===p))render()}catch{toast('사진을 읽지 못했어요. 다른 사진을 선택해 주세요.')}});
app.addEventListener('click',e=>{const b=e.target.closest('[data-feature]');if(!b)return;const p=current()?.plots[plotIndex];switch(b.dataset.feature){case 'harvest':{if(!p||!harvestReady(p)||p.harvestedAt)return;if(confirm(`${meta(p).name} 수확을 기록할까요?`)){p.harvestedAt=day();addRecord(current(),p,'수확을 마쳤어요.');save();render()}break}case 'method':plantingMethod=b.dataset.value;render();break;case 'category':cropCategory=b.dataset.value;render();break;case 'choose':chosenCrop=b.dataset.value;render();break;case 'prepare':navigate('prepare');break;case 'precheck':{const i=Number(b.dataset.index);plantingDraft.checks=plantingDraft.checks.includes(i)?plantingDraft.checks.filter(x=>x!==i):[...plantingDraft.checks,i];render();break}case 'plant':{if(!(typeof isTaskKind==='function'&&isTaskKind(chosenCrop))&&![0,1,2].every(i=>plantingDraft.checks.includes(i))){toast('심기 전 준비 항목을 모두 체크해 주세요.');break}if(current().plots[pendingPlot]){toast('이미 작물이 심어진 칸이에요.');navigate('garden');break}const next=crop(chosenCrop,plantingMethod==='seed'?1:3,true);next.method=plantingMethod;current().plots[pendingPlot]=next;addRecord(current(),next,plantingDraft.memo.trim());state.records.at(-1).event='planting';state.records.at(-1).plantingMethod=plantingMethod;state.records.at(-1).photos=plantingDraft.photos;plantingDraft={checks:[],photos:[],memo:''};plotIndex=pendingPlot;save();navigate('garden');break}case 'check':{if(!p||p.harvestedAt&&day()>p.harvestedAt)return;const key=b.dataset.value;if(key==='observe'){navigate('leaf');break}p.taskChecks||={};const checks=p.taskChecks[day()]||=[];p.taskChecks[day()]=checks;if(completed(p,key)){p.taskChecks[day()]=checks.filter(x=>x!==key);if(key==='water')p.wateredAt=null}else{checks.push(key);if(key==='water'){p.wateredAt=day();p.needsWater=false}}save();render();break}case 'observe':{if(!p)break;const existing=journalTodayEntry('leaf',current(),p);if(existing)journalBegin(existing.id,view==='leaf-result'?journalFlowOrigin:'garden');else{journalEdit=null;journalFlowOrigin=view==='leaf-result'?journalFlowOrigin:'garden';navigate('leaf')}break}case 'leaf-status':{if(!p||!leafStatuses.some(([key])=>key===b.dataset.value))break;p.draftLeafStatus=b.dataset.value;save();render();break}case 'remove-photo':(view==='prepare'?plantingDraft.photos:view==='diagnosis'?diagnosisDraft.photos:view==='leaf'?p.leafDraftPhotos:p.draftPhotos).splice(Number(b.dataset.index),1);if(view==='leaf'||view==='detail')save();render();break;case 'leaf-save':{if(!p)break;const label=leafStatuses.find(([key])=>key===p.draftLeafStatus)?.[1],detail=p.draftLeafStatus==='other'?p.draftLeafOther?.trim():'',photos=p.leafDraftPhotos||[];if(!label&&!photos.length){toast('잎 사진을 추가하거나 상태를 선택해 주세요.');break}if(p.draftLeafStatus==='other'&&!detail){toast('관찰한 변화를 입력해 주세요.');document.querySelector('#leaf-other')?.focus();break}const description=detail?`${label}: ${detail}`:label||'';if(journalEdit&&journalEntries().find(r=>r.id===journalEdit)?.leaf){if(journalUpdateSpecial('leaf',description||journalEntries().find(r=>r.id===journalEdit)?.leaf,photos,detail,null)){p.lastLeafObservation={date:day(),label:description,photo:photos[0]||''};if(label)p.lastLeafStatus={key:p.draftLeafStatus,label:description,date:day()};p.draftLeafStatus=null;p.draftLeafOther='';p.leafDraftPhotos=[];save();navigate('leaf-result')}break}p.lastLeafObservation={date:day(),label:description,photo:photos[0]||''};if(label)p.lastLeafStatus={key:p.draftLeafStatus,label:description,date:day()};addRecord(current(),p,description?`잎 관찰: ${description}`:'잎 사진을 기록했어요.');state.records.at(-1).photos=photos;p.taskChecks||={};const checks=p.taskChecks[day()]||[];p.taskChecks[day()]=checks;if(!checks.includes('observe'))checks.push('observe');p.draftLeafStatus=null;p.draftLeafOther='';p.leafDraftPhotos=[];save();navigate('leaf-result');break}case 'leaf-back':navigate(journalFlowOrigin==='journal'?'journal':'garden');break;case 'journal':{const memo=p.draftMemo?.trim();if(!memo&&!p.draftPhotos?.length){toast('메모나 사진을 추가해 주세요.');return}addRecord(current(),p,memo||'오늘의 작물 사진을 남겼어요.');state.records.at(-1).photos=p.draftPhotos||[];p.draftMemo='';p.draftPhotos=[];save();render();toast('재배일지에 저장했어요.');break}case 'diagnosis':{const existing=p&&journalTodayEntry('diagnosis',current(),p);if(existing)journalBegin(existing.id,view==='leaf-result'?journalFlowOrigin:'garden');else{journalEdit=null;journalFlowOrigin=view==='leaf-result'?journalFlowOrigin:'garden';if(p){diagnosisDraft.kind=p.kind;diagnosisDraft.photos=p.lastLeafObservation?.photo?[p.lastLeafObservation.photo]:[];diagnosisDraft.symptoms=p.lastLeafStatus?.key?[p.lastLeafStatus.key]:[]}navigate('diagnosis')}break}case 'diagnosis-save':journalUpdateSpecial('diagnosis',diagnosisDraft.result,diagnosisDraft.photos,'',journalFlowOrigin==='journal'?'journal':'garden');break;case 'diagnosis-crop':if(CROPS.some(c=>c.id===b.dataset.value)){diagnosisDraft.kind=b.dataset.value;render()}break;case 'diagnosis-symptom':{const key=b.dataset.value;diagnosisDraft.symptoms=diagnosisDraft.symptoms.includes(key)?diagnosisDraft.symptoms.filter(x=>x!==key):[...diagnosisDraft.symptoms,key];render();break}case 'delete-crop':{const farm=current(),index=plotIndex;askConfirm({title:'작물을 삭제할까요?',message:'남긴 일지는 유지돼요.',confirmLabel:'삭제'}).then(ok=>{if(!ok||!farm)return;farm.plots[index]=null;save();navigate('garden')});break}case 'open-task':selected=b.dataset.id;plotIndex=Number(b.dataset.index);navigate('detail');break;case 'task-mode':taskMode=b.dataset.value;render();break}});
const originalJournalPage=journalPage;
journalPage=function(){const html=originalJournalPage();let i=state.records.length;return html.replace(/<\/article>/g,()=>{const r=state.records[--i];return `${r.photos?.length?`<div class="photo-strip">${r.photos.map(src=>`<img class="journal-photo" src="${esc(src)}" alt="재배 기록 사진">`).join('')}</div>`:''}</article>`})};
function journalDemoEditPage(){
  const r=journalPreview?journalDemoEntries.find(entry=>entry.id===journalEdit):journalEntries().find(entry=>entry.id===journalEdit);
  if(!r)return journalPage();
  const leaf=!!r.leaf;
  const symptoms=[['yellow','잎이 변색'],['wilted','시듦'],['spots','잎의 반점'],['holes','구멍'],['slow','성장 느림'],['fruit','과실 이상'],['other','기타']];
  return `<main class="page jr-write-page"><header class="page-head"><div class="back-title"><button class="icon-btn" data-action="nav" data-to="journal" aria-label="뒤로 가기">‹</button><h1>${leaf?'잎 관찰 수정':'AI 진단 수정'}</h1></div></header><p class="help">${esc(r.crop)} · ${esc(r.farm)}${journalPreview?' · 체험용 기록':''}</p>${leaf?`<div class="field-label">직접 확인한 잎 상태</div><div class="leaf-status-options">${leafStatuses.map(([key,label])=>`<button type="button" class="leaf-status-option ${journalDraft.memo===label?'active':''}" data-jr="demo-leaf-status" data-value="${key}" aria-pressed="${journalDraft.memo===label}">${label}</button>`).join('')}</div><div class="field"><label class="field-label" for="jr-demo-detail">관찰 메모</label><textarea id="jr-demo-detail" maxlength="500">${esc(journalDraft.detail||'')}</textarea></div>`:`<div class="field-label">선택한 증상</div><div class="leaf-status-options">${symptoms.map(([key,label])=>`<button type="button" class="leaf-status-option ${journalDraft.symptoms.includes(key)?'active':''}" data-jr="demo-symptom" data-value="${key}" aria-pressed="${journalDraft.symptoms.includes(key)}">${label}</button>`).join('')}</div><div class="field"><label class="field-label" for="jr-demo-result">기록된 진단 결과</label><textarea id="jr-demo-result" maxlength="500">${esc(journalDraft.memo)}</textarea></div>`}<div class="field"><div class="field-label">사진</div><div class="jr-uploads">${journalDraft.photos.map((src,i)=>`<button data-jr="remove-photo" data-index="${i}" aria-label="사진 ${i+1} 삭제"><img src="${esc(src)}" alt="첨부 사진"><span>×</span></button>`).join('')}<label>▣<small>사진 추가</small><input id="jr-photo" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden></label></div></div></main>${footer('<button class="primary" data-jr="demo-save">수정 완료</button>')}`;
}
function journalDemoSave(){
  const r=journalPreview?journalDemoEntries.find(entry=>entry.id===journalEdit):journalEntries().find(entry=>entry.id===journalEdit);
  if(!r)return;
  const value=journalDraft.memo.trim();
  if(!value){toast('내용을 입력해 주세요.');return}
  if(!journalPreview){journalUpdateSpecial(r.leaf?'leaf':'diagnosis',value,journalDraft.photos,journalDraft.detail,'journal');return}
  if(r.leaf){r.leaf=value;r.leafDetail=journalDraft.detail.trim()}
  else{r.diagnosis=value;r.diagnosisSymptoms=[...journalDraft.symptoms]}
  r.photos=[...journalDraft.photos];
  journalEdit=null;
  navigate('journal');
  toast('체험용 기록을 수정했어요.');
}
