app.addEventListener('click',e=>{const b=e.target.closest('[data-jr]');if(!b)return;const action=b.dataset.jr,id=b.dataset.id;if(action==='write')journalBegin();else if(action==='demo-save')journalDemoSave();else if(action==='demo-leaf-status'){journalDraft.memo=leafStatuses.find(([key])=>key===b.dataset.value)?.[1]||'';render()}else if(action==='demo-symptom'){const key=b.dataset.value;journalDraft.symptoms=journalDraft.symptoms.includes(key)?journalDraft.symptoms.filter(x=>x!==key):[...journalDraft.symptoms,key];render()}else if(action==='preview'){journalPreview=!journalPreview;journalFarm='all';journalTab='active';journalCrop='all';journalOpen.clear();journalMenu=null;render()}else if(action==='tab'){journalTab=b.dataset.value;journalCrop='all';journalOpen.clear();render()}else if(action==='farm'){journalFarm=b.dataset.value;journalCrop='all';render()}else if(action==='filter'){journalCrop=b.dataset.value;render()}else if(action==='expand'){journalOpen.has(id)?journalOpen.delete(id):journalOpen.add(id);render()}else if(action==='menu'){journalMenu=journalMenu===id?null:id;render()}else if(action==='edit')journalBegin(id);else if(action==='delete'){askConfirm({title:'이 일지를 삭제할까요?',message:'삭제한 일지는 다시 볼 수 없어요.',confirmLabel:'삭제'}).then(ok=>{if(!ok)return;const before=JSON.stringify(journalLocal);if(journalPreview){journalDemoEntries=journalDemoEntries.filter(r=>r.id!==id);journalMenu=null;render();return}if(id.startsWith('base-'))journalLocal.overrides[id]={...(journalLocal.overrides[id]||{}),hidden:true};else journalLocal.entries=journalLocal.entries.filter(r=>r.id!==id);if(!journalPersist())journalLocal=JSON.parse(before);journalMenu=null;render()})}else if(action==='crop'){if(journalEdit)return;journalDraft.crop=b.dataset.value;render()}else if(action==='remove-photo'){journalDraft.photos.splice(Number(b.dataset.index),1);render()}else if(action==='save'){const previous=journalEdit?journalEntries().find(x=>x.id===journalEdit):null,[farmId,index]=journalDraft.crop.split(':'),f=(journalPreview?journalDemoFarms:state.farms).find(x=>x.id===farmId),p=f?.plots[Number(index)];if(!previous&&!p){toast('작물을 선택해 주세요.');return}if(journalEdit&&!previous)return;const memo=journalDraft.memo.trim();if(!memo&&!journalDraft.photos.length&&!previous?.leaf&&!previous?.diagnosis){toast('사진이나 메모를 추가해 주세요.');return}const before=JSON.stringify(journalLocal),entry={date:journalEdit?previous?.date||new Date().toISOString():new Date().toISOString(),farm:previous?.farm||f.name,crop:previous?.crop||meta(p).name,text:memo||(previous?.leaf||previous?.diagnosis||previous?.event==='planting'?'':'오늘의 작물 사진을 남겼어요.'),photos:[...journalDraft.photos],...(previous?.event==='planting'?{event:'planting',plantingMethod:journalDraft.plantingMethod||previous.plantingMethod}:{}),...(previous?.leaf?{leaf:previous.leaf}:{}),...(previous?.leafDetail?{leafDetail:previous.leafDetail}:{}),...(previous?.diagnosis?{diagnosis:previous.diagnosis}:{})};if(journalPreview){if(journalEdit){const target=journalDemoEntries.find(r=>r.id===journalEdit);if(target)Object.assign(target,entry)}else journalDemoEntries.push({id:`demo-${Date.now()}`,archived:false,tags:[],...entry});journalFarm=entry.farm;journalTab='active';journalCrop='all';journalEdit=null;navigate('journal');return}if(journalEdit?.startsWith('base-')){const override={...(journalLocal.overrides[journalEdit]||{}),...entry};delete override.date;delete override.farm;delete override.crop;journalLocal.overrides[journalEdit]=override}else if(journalEdit){const target=journalLocal.entries.find(x=>x.id===journalEdit);if(target)Object.assign(target,entry)}else journalLocal.entries.push({id:`local-${Date.now()}`, ...entry});if(!journalPersist()){journalLocal=JSON.parse(before);return}journalFarm=entry.farm;journalTab='active';journalCrop='all';navigate('journal');toast(journalEdit?'일지를 수정했어요.':'일지를 올렸어요.')}});
app.addEventListener('change',async e=>{if(e.target.id==='jr-farm'){journalFarm=e.target.value;journalCrop='all';render();return}if(e.target.id==='jr-planting-method'){journalDraft.plantingMethod=e.target.value;return}if(e.target.id!=='jr-photo')return;try{for(const file of [...e.target.files].slice(0,4-journalDraft.photos.length)){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('10MB 이하 JPG, PNG, WEBP 사진을 선택해 주세요.');continue}const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,1000/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();journalDraft.photos.push(canvas.toDataURL('image/jpeg',.7))}render()}catch{toast('사진을 읽지 못했어요. 다른 사진을 선택해 주세요.')}});
app.addEventListener('input',e=>{if(e.target.id==='jr-memo'||e.target.id==='jr-demo-result')journalDraft.memo=e.target.value;if(e.target.id==='jr-memo'){e.target.style.height='auto';e.target.style.height=`${Math.max(160,e.target.scrollHeight)}px`}if(e.target.id==='jr-demo-detail')journalDraft.detail=e.target.value;if(e.target.id==='diagnosis-result')diagnosisDraft.result=e.target.value});
render();
